import React, { useState } from "react";
import ProductContext from "./product-context";

const ProductProvider = (props) => {
  const [openProduct, setOpenProduct] = useState(false);
  const [selectedItem, setSelectedItem] = useState([]);

  const productHandler = () => {
    setOpenProduct(!openProduct); // i am Togglinge the state
  };


  const showProduct = (item) => {
    const itemExists = selectedItem.find((selected) => selected.id === item.id);

    if (itemExists) {
      const updatedItems = selectedItem.map((selected) =>
        selected.id === item.id ? { ...selected, ...item } : selected
      );
      setSelectedItem(updatedItems);
    } else {
      setSelectedItem([...selectedItem, item]);
      setOpenProduct(true);
    }
  };

  const productContext = {
    openProduct,
    selectedItem,
    addItem: showProduct,
    productHandler: productHandler,

    setSelectedItem,
  };

  return (
    <ProductContext.Provider value={productContext}>
      {props.children}
    </ProductContext.Provider>
  );
};

export default ProductProvider;
